package ca.stewark.helioflux.ui.solaractivity
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.layout.ContentScale;import androidx.compose.ui.unit.dp;import ca.stewark.helioflux.core.data.repository.RepositoryState;import ca.stewark.helioflux.core.model.SolarImage;import coil3.compose.AsyncImage
data class SolarImageryPresentation(val title:String,val source:String,val timestampMillis:Long?,val imageUrl:String?)
internal fun solarImageryPresentation(title:String,source:String,state:RepositoryState<SolarImage>):SolarImageryPresentation{val image=when(state){is RepositoryState.Available->state.data;is RepositoryState.Failure->state.retainedData;else->null};return SolarImageryPresentation(title,source,image?.sourceTimestampMillis,image?.url)}
@Composable fun SolarImageryCard(title:String,source:String,state:RepositoryState<SolarImage>,onClick:()->Unit,modifier:Modifier=Modifier){val item=solarImageryPresentation(title,source,state);Card(modifier.clickable(onClick=onClick)){Column{Box(Modifier.fillMaxWidth().aspectRatio(1f)){item.imageUrl?.let{AsyncImage(it,title,Modifier.fillMaxSize(),contentScale=ContentScale.Fit)};if(state is RepositoryState.Loading)CircularProgressIndicator(Modifier.padding(16.dp))};Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(4.dp)){Text(item.title,style=MaterialTheme.typography.titleMedium);Text(item.source,style=MaterialTheme.typography.labelMedium);item.timestampMillis?.let{Text("Updated $it",style=MaterialTheme.typography.bodySmall)};if(state is RepositoryState.Failure)Text("Image unavailable",style=MaterialTheme.typography.bodySmall)}}}}
